int sum_from_one(int a[], int n) {
    if (n == 1) {
        return a[1];
    } else {
        return a[n] + sum_from_one(a, n - 1);
    }
}
int arr[5] = {5, 10, 15, 20, 25};
int result = sum_from_one(arr, 4);

